/*main.js*/
window.$codeShortcut = {
    javascript: [
        {
            label: "快捷代码",
            // icon:'comicon com-code',
            children: [
                {
                    label: "新增/编辑/详情点击显示弹窗",
                    code: `
                    /**
                     * 新增/编辑/详情点击显示弹窗
                     * @param {Object} event
                     * @param {Object} event.row 对应的行数据
                     * @param {Object} event.col 对应的列数据
                     * @param {Object} event.btn 点击的按钮
                     * @param {Object} event.scope 表格对象
                     */
                    action_ev_openDialog: function (event) {
                        var self = this;
                        var btnId = event.btn.id;
                        var btnAddId = "btnAdd";
                        var btnUpdId = "btnUpd";
                        var btnDetailId = "btnDetail";
                        var formId = "data-form_*****";
                        var dlgId = "dialog_*****";
                    
                        // 编辑或详情，回显值
                        if (btnId === btnUpdId || btnId === btnDetailId) {
                            self.misRequest("fetch", {params: { field: "modelData", id: event.row["id"]}}).then(function (res) {
                                self.$setVal(formId, res.data.data);
                            });
                        } else if (btnId === btnAddId) {
                            self.$setVal(formId, {});
                        }
                    
                        //设置模型表单属性
                        var dataFormProp = null;
                        if (btnId === btnAddId) {
                            dataFormProp = {
                                readonly: false,
                                validateGroup: "AddGroup"
                            };
                            // 新增时可以修改
                            //dataFormProp.modelConfig={"dm": { "form.readonly": 0 }};
                        } else if (btnId === btnUpdId) {
                            dataFormProp = {
                                readonly: false,
                                validateGroup: "UpdateGroup1",
                            };
                            // 编辑时不可以修改
                            //dataFormProp.modelConfig={"dm": { "form.readonly": 1 }};
                        } else if (btnId === btnDetailId) {
                            dataFormProp = {
                                readonly: true
                            };
                        }
                        self.$setComProps(formId, dataFormProp);
                    
                        //弹窗
                        var dlgTitle = null;
                        if (btnId === btnAddId) {
                            dlgTitle = "新增";
                        } else if (btnId === btnUpdId) {
                            dlgTitle = "修改";
                        } else if (btnId === btnDetailId) {
                            dlgTitle = "详情";
                        }
                        var dialog = self.$pageDialog({
                            key: dlgId,
                            params: {},
                            winParams: {title: dlgTitle},
                            callback: function () { self.misPage('adv-table_1l2krrec').reloadData() }
                        });
                        //详情隐藏确认按钮
                        if (btnId === btnDetailId) {
                            dialog.$setBtnsProp({"dialogBtnConfirm": {hidden: true}, "dialogBtnCancel": {hidden: false}});
                        }
                    },
                    `
                },
                {
                    label: "先弹提示框再请求api",
                    code: `
                    self.$confirm('确认删除吗?', '确认删除', {
                        type: "error",
                        confirmButtonType: "danger",
                        confirmButtonText: "删除"
                    }).then(function () {
                        self.misRequest('del', {params: {id: event.row["id"]}}).then(function (res) {
                            self.$message.success("删除成功");
                            //刷新表格
                            self.misPage('adv-table_*****').reloadData();
                        });
                    });
                    `
                },
                {
                    label: "提交表单数据到api",
                    code: `
                    var formId = "data-form_*****";
                    self.misPage(formId).validateFormValue().then((formData) => {
                        // 表单校验不通过
                        if (!formData) {
                            return;
                        }
                        var params = formData;
                        params.emptyField = self.getFormUnRequiredFields(formId).join(",");
                        self.misRequest("save", {params: params}).then(function (res) {
                            if (res.data.code === '0') {
                                self.$message.success('保存成功');
                                closeNext();
                            }
                        });
                    });
                    `
                },
                {
                    label: "获取表格勾选/搜索条件对应的搜索参数",
                    code: `
                    var checkedIds = this.misPage("adv-table_*****").getCheckboxAllRecords().map(function (ele) {
                        return ele['id'];
                    }).join(",");
        
                    if (checkedIds) {
                        param.params = {"ids": checkedIds};
                    } else {
                        param.querySetting = this.misPage("adv-search_*****").getSyncQuerySetting();
                    }
                    `
                },
                {
                    label: "表单中代码改变自动填充名称",
                    code: `
                    /**
                     * 表单值改变事件
                     * @param {Object} event 内部参数
                     * @param {Object} event.$com 当前组件
                     * @param {string} event.evName 事件名称
                     * @param {array} event.evArgs 事件参数
                     */
                    form_item_change: function (event) {
                        const arg = event.evArgs;
                        if (arg[0] === "dm") {
                            this.$setModelVal("singleModelFormAdd", "mc", arg[1] + "学年");
                        }
                    }
                    `
                },
                {
                    label: "表单默认填充排序",
                    code: `
                    self.nextOrder(modelName).then(nextOrder => {
                      self.$setVal(formId, {"px":nextOrder});
                    });
                    `
                }
            ]
        }
    ]
};
