//更新待办数量
window.$tabBarBadgeNum = function (request, appCode, eventBus) {
    let api = "";
    let messageKey = "";
    if(appCode == "zyzxydd"){
        api = "/admin/api/query/jasjygl_pub_cxshlb";
        messageKey = "zyzxydd_pub_borrowRecordAuditTabPage";
    }
    //添加获取消息数量的接口
    request({
        url: api,
        method: 'post',
        data:{
            params: {
                field: "page",
                auditPageType: "DSH"
            }
        }
    }).then(res => {
        if(res.code==='0')
            //如果返回成功，更新消息数量
            eventBus.$emit('tab-bar-badge', messageKey,  res.data.totalSize)
    })


}
window.$tabBarDotMessage = function (request, appCode, eventBus) {
    //获取小红点提示
    request({
        url: '/api/msg/count',
        method: 'get',
    }).then(res => {
        if(res.code==='0')
            eventBus.$emit('tab-bar-dot', 'message', res.data.count)
    })
}
window.$injectSearchQs=function(querySetting, modelParams){
    return querySetting.flatMap(item => {
        const valueStr = item.value;
        if (!valueStr || typeof valueStr === 'number' || !valueStr.includes('@yx@')) {
            // 不拆分，直接返回原对象
            return [item];
        }
        //查询院系字段
        const yxidField = Object.keys(modelParams).find(key => key.includes('.yxid')) || 'yxid';
        return valueStr.split(',').map((value, index) => {
            value = value.slice(4);
            const [mainValue, yxValue] = value.split('@');
            return [
                {
                    name: item.name,
                    value: mainValue,
                    linkOpt: index === 0 ? 'and' : 'or',
                    builder: 'equal'
                },
                {
                    name: yxidField,
                    value: yxValue,
                    linkOpt: 'and',
                    builder: 'equal'
                }
            ];
        });
    });
}

// 推荐：通过 $TECH_ENUM.Hooks 引用钩子名，避免裸字符串拼写错误
window.$TECH_SYS.hook.add(
    $TECH_ENUM.Hooks.resolveComponentUrl,
    (defaultUrl, comInfo) => {
        const { cmpCode } = comInfo; // 组件代码、组件所在应用代码
        return `/customCmp/${cmpCode}/${cmpCode}.umd.min.js`;
    },
);

;(function (win) {
    win.$AxiosConfig = {
        // 通过枚举接口url，判断config.url中含有枚举中的任意一个，就添加加密参数
        request: function (config) {
            //拦截注入url
            const mapUrl = [
                '/admin/upms/sysUser/list',
                '/admin/dict/list/columnxtype',
                '/admin/page/design/save',
                '/admin/flow/flowOperation/getFlowInfo',
                '/admin/flow/flowOperation/listFlowTaskComment',
                '/admin/upms/sysDept/listDictByIds',
                '/admin/upms/sysUser/managelist',
                '/admin/flow/flowOperation/listFlowTrack',
                '/admin/upms/sysDept/listDict',
                '/admin/upms/sysDept/list/user',
                '/admin/upms/sysUser/teacher/list',
                '/admin/upms/sysDept/list/teacher',
                '/admin/upms/sysDept/student/listDict',
                '/admin/upms/sysUser/student/list',
                '/admin/upms/sysDept/list/student'
            ]
            let pathUrl = config.url.replace(win.$GLOBAL_CONFIG.apiPath, '');
            pathUrl = pathUrl.charAt(0) === '/' ? pathUrl : '/' + pathUrl;
            if (mapUrl.includes(pathUrl) && config.method == 'post') {
                config.data = config.data ? window.$Utils.encryptedData(config.data) : null
                config.headers = Object.assign(config.headers, {
                    'Content-Type': 'application/json'
                });
            }
            return config
        },
        response: function (config, data, response) {
            // 添加空值检查和错误处理
            if (data && window.$Utils && typeof window.$Utils.decryptedData === 'function') {
                try {
                    data = window.$Utils.decryptedData(data);
                } catch (error) {
                    console.error('数据解密失败:', error);
                }
            }
            return data
        }
    }
})(window)